"""Generate deterministic gzip assets from web/ for inclusion in the sketch."""

import gzip
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
ASSETS = {
    "DASHBOARD_HTML": "index.html",
    "UI_CSS": "ui.css",
    "THEME_JS": "theme.js",
    "SORT_JS": "sort.js",
    "HEATMAP_JS": "heatmap.js",
    "DASHBOARD_JS": "dashboard.js",
    "ADMIN_JS": "admin.js",
    "POLICIES_JS": "policies.js",
    "TIMEZONES_JSON": "timezones.json",
}


def main():
    lines = [
        "#pragma once",
        "#include <Arduino.h>",
        "// Generated by tools/build_web_assets.py; edit web/ sources instead.",
    ]
    for symbol, filename in ASSETS.items():
        source = (ROOT / "web" / filename).read_bytes()
        compressed = gzip.compress(source, compresslevel=9, mtime=0)
        lines.append(f"const uint8_t {symbol}[] PROGMEM = {{")
        for offset in range(0, len(compressed), 24):
            row = ",".join(str(byte) for byte in compressed[offset : offset + 24])
            lines.append(f"  {row},")
        lines.append("};")

    destination = ROOT / "IntrusionMonitor" / "WebAssets.h"
    destination.write_text("\n".join(lines) + "\n")
    print("Generated compressed dashboard assets.")


if __name__ == "__main__":
    main()
